{
    /** @return array<int, array<string, array{question: string, options: list<string>, explanation: string}>> */
    public static function all(): array
    {
        $names = self::nameOptions();
        $rowsByLocale = self::rows();
        $result = [];
        foreach (['en', 'de', 'fr', 'es', 'ru'] as $locale) {
            foreach ($rowsByLocale[$locale] as $id => $row) {
                $result[$id][$locale] = [
                    'question' => $row[0],
                    'options' => $row[2] ?? $names[$id],
                    'explanation' => $row[1],
                ];
            }
        }
        ksort($result);

        return $result;
    }

