                57 => ['What is the name of the main character in the first season of Chainsaw Man?', 'The first season follows Denji, a young devil hunter.'],
                58 => ['What is the name of Denji’s dog-like devil companion?', 'Denji’s companion at the start of Chainsaw Man is Pochita.'],
                59 => ['Which tool is associated with Pochita’s devil power in Chainsaw Man?', 'Pochita is the Chainsaw Devil, whose power is connected to Denji’s transformation.', ['A hammer', 'A chainsaw', 'A drill', 'An axe']],
                60 => ['Who is the author of the Chainsaw Man manga?', 'Chainsaw Man was created by Tatsuki Fujimoto.'],
            ],
            'es' => [
                1 => ['¿Cómo se llama el protagonista del anime Naruto?', 'El protagonista es Naruto Uzumaki, un estudiante de la academia ninja.'],
                2 => ['¿De qué aldea procede Naruto Uzumaki?', 'Naruto vive en Konoha, la Aldea Oculta de la Hoja.', ['Aldea Oculta de la Arena', 'Aldea Oculta de la Niebla', 'Aldea Oculta de la Nube', 'Aldea Oculta de la Hoja']],
                3 => ['¿Qué profesor enseña a Naruto en la academia ninja al comienzo de la serie?', 'Iruka Umino es el profesor de Naruto en la academia ninja.'],
                4 => ['¿Quién creó el manga en el que se basa el anime Naruto?', 'Masashi Kishimoto es el autor del manga Naruto.'],
                5 => ['¿Con qué título sueña Monkey D. Luffy en One Piece?', 'Luffy se hace a la mar con el sueño de convertirse en el Rey de los Piratas.', ['Almirante de la Marina', 'Rey de los Piratas', 'Hokage', 'Rey de los Alquimistas']],
                6 => ['¿Qué propiedad tiene el cuerpo de Luffy al comienzo de One Piece?', 'Una de las habilidades básicas de Luffy es estirar su cuerpo como la goma.', ['Se convierte en hielo', 'Se vuelve invisible', 'Se estira como la goma', 'Atraviesa paredes']],
                7 => ['¿Qué habilidad pierde Luffy tras obtener su extraordinario poder?', 'El precio del extraordinario poder de Luffy es perder la capacidad de nadar.', ['Nadar', 'Leer', 'Saltar', 'Correr']],
                8 => ['¿Quién es el autor del manga One Piece?', 'One Piece fue creado por Eiichiro Oda.'],
                9 => ['¿Qué estudiante encuentra el misterioso cuaderno en Death Note?', 'Light Yagami encuentra el Death Note y comienza a descubrir cómo funciona.'],
                10 => ['¿Qué clase de objeto es el Death Note?', 'El Death Note es un cuaderno sobrenatural vinculado a los dioses de la muerte.', ['Un cuaderno', 'Un anillo', 'Una máscara', 'Una espada']],
                11 => ['¿Cómo se llama a los dioses de la muerte en Death Note?', 'Los dioses de la muerte del mundo de Death Note se llaman shinigami.', ['Saiyan', 'Shinigami', 'Pilares', 'Hokage']],
                12 => ['¿Qué dúo creó el manga Death Note?', 'Tsugumi Ohba escribió el guion y Takeshi Obata realizó los dibujos.', ['ONE y Yusuke Murata', 'Riichiro Inagaki y Boichi', 'Eiichiro Oda y Tite Kubo', 'Tsugumi Ohba y Takeshi Obata']],
                13 => ['¿Cuál es la verdadera profesión de Twilight en SPY × FAMILY?', 'Twilight es un espía que forma una familia para una misión secreta.', ['Espía', 'Jugador profesional de voleibol', 'Alquimista', 'Pirata']],
                14 => ['¿Qué habilidad extraordinaria tiene Anya en SPY × FAMILY?', 'Anya es telépata y puede leer los pensamientos de otras personas.', ['Controlar el clima', 'Detener el tiempo', 'Leer la mente', 'Convertir metales en oro']],
                15 => ['¿Qué profesión secreta ejerce Yor en SPY × FAMILY?', 'Yor oculta a quienes la rodean su trabajo como asesina a sueldo.', ['Detective', 'Asesina a sueldo', 'Cazadora de tesoros', 'Piloto de carreras']],
                16 => ['¿Qué apellido usan Loid, Yor y Anya en SPY × FAMILY?', 'Los personajes viven juntos como la familia Forger.'],
                17 => ['¿Cómo se llama el protagonista de Demon Slayer: Kimetsu no Yaiba?', 'Tanjiro Kamado es el héroe cuyo viaje da comienzo a esta historia.'],
                18 => ['¿Qué parentesco tiene Nezuko con Tanjiro en Demon Slayer?', 'Nezuko Kamado es la hermana menor de Tanjiro.', ['Es su profesora', 'Es su prima', 'Es su madre', 'Es su hermana menor']],
                19 => ['¿En qué era de Japón comienza Demon Slayer?', 'El comienzo de la historia de Tanjiro transcurre en el Japón de la era Taisho.'],
                20 => ['¿Qué vende Tanjiro para ganarse la vida al principio de Demon Slayer?', 'Antes de iniciar su viaje, Tanjiro se gana la vida vendiendo carbón vegetal.', ['Pescado', 'Seda', 'Carbón vegetal', 'Libros']],
                21 => ['¿Cómo se llama el protagonista de My Hero Academia?', 'Izuku Midoriya es un chico que sueña con convertirse en héroe.'],
                22 => ['¿Cómo se llaman las habilidades extraordinarias de las personas en My Hero Academia?', 'Los superpoderes del mundo de My Hero Academia se conocen como dones.', ['Dones', 'Bankai', 'Nen', 'Stands']],
                23 => ['¿Qué porcentaje de la población tiene superpoderes en el mundo de My Hero Academia?', 'En este mundo, alrededor del 80 por ciento de las personas nace con habilidades extraordinarias.', ['20 por ciento', '40 por ciento', '60 por ciento', '80 por ciento']],
                24 => ['¿Quién es el autor del manga My Hero Academia?', 'El manga My Hero Academia fue creado por Kohei Horikoshi.'],
                25 => ['¿Qué deporte es el tema principal del anime Haikyu!!?', 'Haikyu!! trata sobre el voleibol y la competición entre equipos escolares.', ['Baloncesto', 'Fútbol', 'Béisbol', 'Voleibol']],
                26 => ['¿Qué personaje de Haikyu!! quiere demostrar que ser bajo no impide jugar al voleibol?', 'Shoyo Hinata compensa su baja estatura con determinación y una gran capacidad de salto.'],
                27 => ['¿Qué apodo tiene el jugador de voleibol que inspira a Hinata en Haikyu!!?', 'Hinata se inspira en un jugador conocido como el Pequeño Gigante.', ['Príncipe Negro', 'Lobo Blanco', 'Pequeño Gigante', 'Zorro Plateado']],
                28 => ['¿Qué rival de Hinata se convierte en su compañero de equipo al comienzo de Haikyu!!?', 'Tobio Kageyama, antiguo rival de Hinata, entra en el mismo equipo.'],
                29 => ['¿Qué le ocurre a la humanidad al comienzo de Dr. STONE?', 'La historia comienza con la misteriosa petrificación de la humanidad.', ['Se convierte en piedra', 'Es transportada a Marte', 'Pierde la gravedad', 'Se convierte en animales']],
                30 => ['¿Qué personaje de Dr. STONE se dedica especialmente a la ciencia?', 'Senku utiliza sus conocimientos científicos en el mundo posterior a la petrificación.'],
                31 => ['¿Con qué quieren reconstruir la civilización Senku y Taiju en Dr. STONE?', 'Los personajes planean restaurar la civilización gracias a los avances científicos.', ['Con hechizos mágicos', 'Con viajes a otra dimensión', 'Con poderes de dragones', 'Con la ciencia']],
                32 => ['¿Qué amigo encuentra a Senku tras liberarse de la petrificación al comienzo de Dr. STONE?', 'Después de liberarse de su envoltura de piedra, Taiju encuentra a su amigo Senku.'],
                33 => ['¿Cómo se llaman los hermanos Elric de Fullmetal Alchemist?', 'Los protagonistas son los hermanos Edward y Alphonse Elric.', ['Gon y Killua', 'Naruto y Sasuke', 'Edward y Alphonse', 'Denji y Aki']],
                34 => ['¿A qué está ligada el alma de Alphonse al comienzo de Fullmetal Alchemist?', 'Tras un ritual alquímico fallido, el alma de Alphonse queda ligada a una armadura.', ['A una armadura', 'A un árbol', 'A una estatua de piedra', 'A un cuaderno']],
                35 => ['¿Qué buscan los hermanos Elric para recuperar sus cuerpos?', 'Edward y Alphonse esperan que la Piedra Filosofal les permita recuperar sus cuerpos.', ['Las Bolas de Dragón', 'El Cristal de Plata', 'El One Piece', 'La Piedra Filosofal']],
                36 => ['¿Cómo se llaman las prótesis mecánicas que usa Edward Elric?', 'Las extremidades mecánicas de Edward son prótesis llamadas automail.'],
                37 => ['¿Cómo se llama el protagonista de Jujutsu Kaisen?', 'Jujutsu Kaisen sigue a Yuji Itadori en un mundo de maldiciones.'],
                38 => ['¿Quién creó el manga Jujutsu Kaisen?', 'El manga Jujutsu Kaisen fue creado por Gege Akutami.'],
                39 => ['¿Qué dos ciudades representan las escuelas durante el intercambio de la primera temporada de Jujutsu Kaisen?', 'En el intercambio participan estudiantes de las escuelas de hechicería de Tokio y Kioto.', ['Osaka y Nara', 'Tokio y Kioto', 'Nagoya y Kobe', 'Sapporo y Fukuoka']],
                40 => ['¿De qué seres sobrenaturales protegen a las personas los hechiceros de Jujutsu Kaisen?', 'Los hechiceros combaten a los espíritus malditos que amenazan a las personas.', ['Titanes', 'Androides', 'Espíritus malditos', 'Piratas espaciales']],
                41 => ['¿Cuántas Bolas de Dragón hay que reunir para invocar al dragón en el Dragon Ball original?', 'Para invocar al dragón se necesita el conjunto de siete Bolas de Dragón.', ['Cinco', 'Siete', 'Nueve', 'Doce']],
                42 => ['¿Quién construye el radar para buscar las Bolas de Dragón al comienzo de Dragon Ball?', 'Bulma construye un radar que indica dónde están las Bolas de Dragón.'],
                43 => ['¿Quién creó el manga Dragon Ball?', 'Dragon Ball fue creado por Akira Toriyama.'],
                44 => ['¿Qué rasgo físico inusual tiene el pequeño Son Goku al comienzo de Dragon Ball?', 'Al comienzo de la historia, el pequeño Son Goku tiene una cola de mono.', ['Cuernos', 'Alas', 'Una cola de mono', 'Una aleta de pez']],
                45 => ['¿Cómo se llama la chica que se transforma en Sailor Moon?', 'Usagi Tsukino se transforma en la guerrera Sailor Moon.'],
                46 => ['¿Qué título vuelve a contar los inicios de Sailor Moon basándose en el manga?', 'Sailor Moon Crystal vuelve a presentar los inicios del manga de Naoko Takeuchi.'],
                47 => ['¿Quién creó el manga Sailor Moon?', 'Sailor Moon fue creado por Naoko Takeuchi.'],
                48 => ['¿Qué cristal legendario buscan las guerreras al principio de Sailor Moon Crystal?', 'El legendario Cristal de Plata es un objetivo importante de la búsqueda de las guerreras.', ['Dorado', 'Rubí', 'Zafiro', 'Plateado']],
                49 => ['¿Qué personaje parte en busca de su padre en Hunter × Hunter?', 'El viaje de Gon en busca de su padre es el punto de partida de la serie.'],
                50 => ['¿Qué acreditación se obtiene al aprobar el examen de Cazador en Hunter × Hunter?', 'Aprobar el exigente examen permite obtener una licencia de Cazador.', ['Una licencia de Cazador', 'El título de Hokage', 'Un cinturón de campeón de voleibol', 'El rango de almirante']],
                51 => ['¿Quién es el autor del manga Hunter × Hunter?', 'Hunter × Hunter fue creado por Yoshihiro Togashi.'],
                52 => ['¿Qué otro manga creó Yoshihiro Togashi, autor de Hunter × Hunter?', 'Yoshihiro Togashi también es el autor de YuYu Hakusho.'],
                53 => ['¿Cómo se llama el protagonista de One-Punch Man?', 'El protagonista es Saitama, un personaje de fuerza extraordinaria.'],
                54 => ['¿Qué rasgo físico distingue a Saitama en One-Punch Man?', 'Saitama es reconocible, entre otras cosas, por su cabeza calva.', ['Pelo largo y azul', 'Una barba verde', 'Una cresta rosa', 'Una cabeza calva']],
                55 => ['¿Qué clase de adversario le cuesta encontrar a Saitama en One-Punch Man?', 'Su enorme fuerza hace que Saitama rara vez encuentre un rival a su altura.', ['Uno tan fuerte que suponga un desafío', 'Uno que sepa leer', 'Uno que lleve gafas', 'Uno que venga de Japón']],
                56 => ['¿Qué seudónimo usa el autor del webcómic original de One-Punch Man?', 'El webcómic original de One-Punch Man fue creado por un autor conocido como ONE.'],
                57 => ['¿Cómo se llama el protagonista de la primera temporada de Chainsaw Man?', 'La primera temporada cuenta la historia de Denji, un joven cazador de demonios.'],
                58 => ['¿Cómo se llama el demonio parecido a un perro que acompaña a Denji?', 'El compañero de Denji al comienzo de Chainsaw Man es Pochita.'],
                59 => ['¿Con qué herramienta está relacionado el poder demoníaco de Pochita en Chainsaw Man?', 'Pochita es el Demonio Motosierra, cuyo poder está relacionado con la transformación de Denji.', ['Un martillo', 'Una motosierra', 'Un taladro', 'Un hacha']],
                60 => ['¿Quién es el autor del manga Chainsaw Man?', 'Chainsaw Man fue creado por Tatsuki Fujimoto.'],
            ],
            'ru' => [
                1 => ['Как зовут главного героя аниме «Наруто»?', 'Главный герой — Наруто Узумаки, ученик академии ниндзя.'],
                2 => ['Из какой деревни родом Наруто Узумаки?', 'Наруто живёт в Конохе, Деревне Скрытого Листа.', ['Деревня Скрытого Песка', 'Деревня Скрытого Тумана', 'Деревня Скрытого Облака', 'Деревня Скрытого Листа']],
                3 => ['Кто учит Наруто в академии ниндзя в начале сериала?', 'Ирука Умино — учитель Наруто в академии ниндзя.'],
                4 => ['Кто создал мангу, по которой снято аниме «Наруто»?', 'Автор манги «Наруто» — Масаси Кисимото.'],
                5 => ['О каком титуле мечтает Монки Д. Луффи в One Piece?', 'Луффи отправляется в море с мечтой стать Королём пиратов.', ['Адмирал Морского дозора', 'Король пиратов', 'Хокаге', 'Король алхимиков']],
                6 => ['Какое свойство имеет тело Луффи в начале One Piece?', 'Одна из основных способностей Луффи — растягивать тело, словно резину.', ['Превращается в лёд', 'Становится невидимым', 'Растягивается, словно резина', 'Проходит сквозь стены']],
                7 => ['Какую способность теряет Луффи после обретения необычной силы?', 'Платой за необычную силу Луффи становится потеря способности плавать.', ['Плавать', 'Читать', 'Прыгать', 'Бегать']],
                8 => ['Кто является автором манги One Piece?', 'One Piece создал Эйитиро Ода.'],
                9 => ['Какой школьник находит загадочную тетрадь в Death Note?', 'Лайт Ягами находит Тетрадь смерти и начинает изучать её действие.'],
                10 => ['Что представляет собой Тетрадь смерти в Death Note?', 'Тетрадь смерти — сверхъестественная тетрадь, связанная с богами смерти.', ['Тетрадь', 'Кольцо', 'Маска', 'Меч']],
                11 => ['Как называют богов смерти в Death Note?', 'Богов смерти в мире Death Note называют синигами.', ['Сайяны', 'Синигами', 'Столпы', 'Хокаге']],
                12 => ['Какой дуэт создал мангу Death Note?', 'Цугуми Оба написал сценарий, а Такэси Обата создал рисунки.', ['ONE и Yusuke Murata', 'Riichiro Inagaki и Boichi', 'Eiichiro Oda и Tite Kubo', 'Tsugumi Ohba и Takeshi Obata']],
                13 => ['Кем на самом деле работает Сумрак в SPY × FAMILY?', 'Сумрак — шпион, который создаёт семью ради выполнения секретной миссии.', ['Шпионом', 'Профессиональным волейболистом', 'Алхимиком', 'Пиратом']],
                14 => ['Какой необычной способностью обладает Аня в SPY × FAMILY?', 'Аня — телепат и умеет читать мысли других людей.', ['Управляет погодой', 'Останавливает время', 'Читает мысли', 'Превращает металлы в золото']],
                15 => ['Какую тайную работу выполняет Йор в SPY × FAMILY?', 'Йор скрывает от окружающих свою работу наёмной убийцей.', ['Детектив', 'Наёмная убийца', 'Охотница за сокровищами', 'Автогонщица']],
                16 => ['Какую фамилию используют Лойд, Йор и Аня в SPY × FAMILY?', 'Герои живут вместе как семья Форджер.'],
                17 => ['Как зовут главного героя Demon Slayer: Kimetsu no Yaiba?', 'Тандзиро Камадо — герой, с путешествия которого начинается эта история.'],
                18 => ['Кем Нэдзуко приходится Тандзиро в Demon Slayer?', 'Нэдзуко Камадо — младшая сестра Тандзиро.', ['Учительницей', 'Двоюродной сестрой', 'Матерью', 'Младшей сестрой']],
                19 => ['В какую эпоху японской истории начинается Demon Slayer?', 'Начало истории Тандзиро происходит в Японии эпохи Тайсё.'],
                20 => ['Что Тандзиро продаёт, чтобы заработать на жизнь в начале Demon Slayer?', 'До начала путешествия Тандзиро зарабатывает продажей древесного угля.', ['Рыбу', 'Шёлк', 'Древесный уголь', 'Книги']],
                21 => ['Как зовут главного героя My Hero Academia?', 'Идзуку Мидория — мальчик, мечтающий стать героем.'],
                22 => ['Как называются необычные способности людей в My Hero Academia?', 'Сверхспособности в мире My Hero Academia называются причудами.', ['Причуды', 'Банкай', 'Нэн', 'Стенды']],
                23 => ['Какой процент населения обладает сверхспособностями в мире My Hero Academia?', 'В этом мире около 80 процентов людей рождаются с необычными способностями.', ['20 процентов', '40 процентов', '60 процентов', '80 процентов']],
                24 => ['Кто является автором манги My Hero Academia?', 'Мангу My Hero Academia создал Кохэй Хорикоси.'],
                25 => ['Какой вид спорта является главной темой аниме Haikyu!!?', 'Haikyu!! рассказывает о волейболе и соперничестве школьных команд.', ['Баскетбол', 'Футбол', 'Бейсбол', 'Волейбол']],
                26 => ['Какой герой Haikyu!! хочет доказать, что маленький рост не мешает играть в волейбол?', 'Сёё Хината компенсирует маленький рост упорством и высоким прыжком.'],
                27 => ['Какое прозвище носит волейболист, вдохновивший Хинату в Haikyu!!?', 'Хината вдохновляется игроком по прозвищу Маленький гигант.', ['Чёрный принц', 'Белый волк', 'Маленький гигант', 'Серебряный лис']],
                28 => ['Какой соперник Хинаты становится его товарищем по команде в начале Haikyu!!?', 'Тобио Кагэяма, бывший соперник Хинаты, попадает в ту же команду.'],
                29 => ['Что происходит с человечеством в начале Dr. STONE?', 'История начинается с загадочного окаменения человечества.', ['Превращается в камень', 'Попадает на Марс', 'Лишается гравитации', 'Превращается в животных']],
                30 => ['Какой герой Dr. STONE особенно увлечён наукой?', 'Сэнку использует научные знания в мире после окаменения.'],
                31 => ['С помощью чего Сэнку и Тайдзю хотят восстановить цивилизацию в Dr. STONE?', 'Герои собираются восстановить цивилизацию благодаря научным достижениям.', ['Магических заклинаний', 'Путешествий в другое измерение', 'Сил драконов', 'Науки']],
                32 => ['Какой друг встречает Сэнку после освобождения от окаменения в начале Dr. STONE?', 'Освободившись от каменной оболочки, Тайдзю находит своего друга Сэнку.'],
                33 => ['Как зовут братьев Элрик из Fullmetal Alchemist?', 'Главные герои — братья Эдвард и Альфонс Элрик.', ['Gon и Killua', 'Naruto и Sasuke', 'Edward и Alphonse', 'Denji и Aki']],
                34 => ['К чему привязана душа Альфонса в начале Fullmetal Alchemist?', 'После неудачного алхимического ритуала душа Альфонса оказывается привязана к доспехам.', ['К доспехам', 'К дереву', 'К каменной статуе', 'К тетради']],
                35 => ['Что ищут братья Элрик, чтобы вернуть свои тела?', 'Эдвард и Альфонс надеются вернуть свои тела с помощью Философского камня.', ['Жемчужины дракона', 'Серебряный кристалл', 'One Piece', 'Философский камень']],
                36 => ['Как называются механические протезы Эдварда Элрика?', 'Механические конечности Эдварда — протезы, известные как автомейл.'],
                37 => ['Как зовут главного героя Jujutsu Kaisen?', 'Jujutsu Kaisen рассказывает о Юдзи Итадори в мире проклятий.'],
                38 => ['Кто создал мангу Jujutsu Kaisen?', 'Автор манги Jujutsu Kaisen — Гэгэ Акутами.'],
                39 => ['Какие два города представляют школы на обмене в первом сезоне Jujutsu Kaisen?', 'В обмене участвуют ученики школ магии из Токио и Киото.', ['Осака и Нара', 'Токио и Киото', 'Нагоя и Кобе', 'Саппоро и Фукуока']],
                40 => ['От каких сверхъестественных существ маги защищают людей в Jujutsu Kaisen?', 'Маги сражаются с проклятыми духами, угрожающими людям.', ['От титанов', 'От андроидов', 'От проклятых духов', 'От космических пиратов']],
                41 => ['Сколько Жемчужин дракона нужно собрать для призыва дракона в оригинальном Dragon Ball?', 'Для призыва дракона нужен полный набор из семи Жемчужин дракона.', ['Пять', 'Семь', 'Девять', 'Двенадцать']],
                42 => ['Кто создаёт радар для поиска Жемчужин дракона в начале Dragon Ball?', 'Булма создаёт радар, показывающий расположение Жемчужин дракона.'],
                43 => ['Кто создал мангу Dragon Ball?', 'Dragon Ball создал Акира Торияма.'],
